// Jabs, Mistress of Mockery
// status: ready
// If a triggered ability of a permanent you control but don't own triggers, that ability triggers an additional time.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_trigger_rule(q: &dyn Query, asker: &Asker, event: &Event, triggering: &Triggering) -> bool { true && (triggering.permanent && ((q.chars(triggering.source).is(CardType::Artifact) || q.chars(triggering.source).is(CardType::Battle) || q.chars(triggering.source).is(CardType::Creature) || q.chars(triggering.source).is(CardType::Enchantment) || q.chars(triggering.source).is(CardType::Land) || q.chars(triggering.source).is(CardType::Planeswalker)) && Some(asker.controller) == Some(triggering.controller) && ({ let other = Some(asker.controller); q.state().apnap().filter(|p| Some(*p) != other).collect::<Vec<PlayerId>>() }).contains(&q.state().obj(triggering.source).owner))) && true }

